//! Yazi file manager theme.
//!
//! The generated file is a complete `theme.toml` for `~/.config/yazi/`.

use theme_engine::LoadedTheme;

use crate::{Integration, RenderError, require, validate_toml};

pub struct Yazi;

impl Integration for Yazi {
    fn id(&self) -> &'static str {
        "yazi"
    }

    fn name(&self) -> &'static str {
        "Yazi file manager"
    }

    fn relative_path(&self) -> &'static str {
        "yazi/theme.toml"
    }

    fn programs(&self) -> &'static [&'static str] {
        &["yazi"]
    }

    fn render(&self, theme: &LoadedTheme) -> String {
        render(theme)
    }

    fn validate(&self, content: &str) -> Result<(), RenderError> {
        require("yazi", content, "[mgr]")?;
        require("yazi", content, "[status]")?;
        require("yazi", content, "[tabs]")?;
        require("yazi", content, "[filetype]")?;
        validate_toml(content)
    }
}

fn style(fg: &str, bg: Option<&str>) -> String {
    match bg {
        Some(bg) => format!("{{ fg = \"{fg}\", bg = \"{bg}\" }}"),
        None => format!("{{ fg = \"{fg}\" }}"),
    }
}

/// Generates a Yazi theme from the active theme.
pub fn render(theme: &LoadedTheme) -> String {
    let c = &theme.colors;

    let bg = c.background.to_hex();
    let surface = c.surface.to_hex();
    let surface_alt = c.surface_alt.to_hex();
    let fg = c.text.to_hex();
    let muted = c.text_muted.to_hex();
    let border = c.border.to_hex();
    let primary = c.primary.to_hex();
    let secondary = c.secondary.to_hex();
    let success = c.success.to_hex();
    let warning = c.warning.to_hex();
    let error = c.error.to_hex();

    let mut output = String::new();

    output.push_str("# Generated by My Linux Theme Engine. Do not edit manually.\n");
    output.push_str("# Yazi reads this file as ~/.config/yazi/theme.toml.\n\n");

    output.push_str("[app]\n");
    output.push_str(&format!("overall = {{ bg = \"{bg}\" }}\n\n"));

    output.push_str("[mgr]\n");
    output.push_str(&format!("cwd = {}\n", style(&primary, None)));
    output.push_str(&format!("hovered = {}\n", style(&bg, Some(&primary))));
    output.push_str(&format!("preview_title = {}\n", style(&secondary, None)));
    output.push_str(&format!("symlink_target = {}\n", style(&success, None)));
    output.push_str(&format!("border_style = {}\n", style(&border, None)));
    output.push_str(&format!(
        "marker_copied = {}\n",
        style(&success, Some(&success))
    ));
    output.push_str(&format!("marker_cut = {}\n", style(&error, Some(&error))));
    output.push_str(&format!(
        "marker_marked = {}\n",
        style(&secondary, Some(&secondary))
    ));
    output.push_str(&format!(
        "marker_selected = {}\n",
        style(&warning, Some(&warning))
    ));
    output.push_str("marker_symbol = \"│\"\n");
    output.push_str(&format!("count_copied = {}\n", style(&bg, Some(&success))));
    output.push_str(&format!("count_cut = {}\n", style(&bg, Some(&error))));
    output.push_str(&format!(
        "count_selected = {}\n\n",
        style(&bg, Some(&warning))
    ));

    output.push_str("[status]\n");
    output.push_str(&format!("perm_type = {}\n", style(&warning, None)));
    output.push_str(&format!("perm_read = {}\n", style(&success, None)));
    output.push_str(&format!("perm_write = {}\n", style(&error, None)));
    output.push_str(&format!("perm_exec = {}\n", style(&secondary, None)));
    output.push_str(&format!("perm_sep = {}\n\n", style(&border, None)));

    output.push_str("[tabs]\n");
    output.push_str(&format!(
        "active = {{ fg = \"{bg}\", bg = \"{primary}\", bold = true }}\n"
    ));
    output.push_str(&format!("inactive = {}\n\n", style(&muted, Some(&surface))));

    output.push_str("[filetype]\nrules = [\n");
    output.push_str(&format!(
        "  {{ mime = \"image/*\", fg = \"{secondary}\" }},\n"
    ));
    output.push_str(&format!(
        "  {{ mime = \"{{audio,video}}/*\", fg = \"{warning}\" }},\n"
    ));
    output.push_str(&format!(
        "  {{ mime = \"inode/empty\", fg = \"{muted}\" }},\n"
    ));
    output.push_str(&format!(
        "  {{ url = \"*\", is = \"orphan\", fg = \"{error}\" }},\n"
    ));
    output.push_str(&format!("  {{ url = \"*/\", fg = \"{primary}\" }},\n"));
    output.push_str(&format!("  {{ url = \"*\", fg = \"{fg}\" }},\n"));
    output.push_str("]\n\n");

    output.push_str(&format!(
        "# surface {surface} / {surface_alt} matches the theme panels.\n"
    ));

    output
}

#[cfg(test)]
mod tests {
    use super::*;
    use theme_engine::Registry;

    fn theme() -> LoadedTheme {
        Registry::new(vec!["../../themes".into()])
            .load("cyberpunk")
            .expect("cyberpunk should load")
    }

    #[test]
    fn renders_parseable_theme_toml() {
        let conf = render(&theme());

        assert!(conf.contains("[mgr]"));
        assert!(conf.contains("cwd = { fg = \"#FF235A\" }"));
        assert!(conf.contains("marker_symbol = \"│\""));

        let parsed: toml::Value =
            toml::from_str(&conf).expect("generated theme must be valid TOML");

        assert!(parsed.get("mgr").is_some());
        assert!(parsed.get("filetype").is_some());
    }

    #[test]
    fn validates_yazi_theme() {
        assert!(Yazi.validate(&render(&theme())).is_ok());
        assert!(Yazi.validate("[mgr]\ncwd = \n").is_err());
    }
}
